package com.simpleengine.game;
import java.io.File;import java.util.ArrayList;import java.util.List;
public final class MinecraftArgumentResolver{private MinecraftArgumentResolver(){} public static List<String> resolve(List<String> raw,MinecraftLaunchContext c){MinecraftArguments v=new MinecraftArguments().put("auth_player_name",c.username).put("auth_uuid",c.uuid).put("auth_access_token",c.accessToken).put("user_type",c.userType).put("version_type",c.versionType).put("game_directory",abs(c.gameDirectory)).put("assets_root",abs(c.assetsDirectory)).put("assets_index_name",c.assetIndexName).put("natives_directory",abs(c.nativesDirectory)).put("launcher_name",c.launcherName).put("launcher_version",c.launcherVersion).put("version_name",c.versionType).put("clientid","").put("auth_xuid","").put("resolution_width","854").put("resolution_height","480");List<String> out=new ArrayList<>();if(raw!=null)for(String s:raw){if(s==null||s.isEmpty())continue;String x=v.resolve(s);if(x.indexOf("${")>=0)continue;out.add(x);}return out;}private static String abs(File f){return f==null?"":f.getAbsolutePath();}}
